const body = $input.item.json.body || $input.item.json;
const text = body.text || '';

// Extraer números
const regex = /-?\d+(\.\d+)?/g;
const matches = text.match(regex);

if (!matches || matches.length === 0) {
  return { json: { error: 'No se encontraron números en el texto proporcionado.' } };
}

const numbers = matches.map(Number);
const sorted = [...numbers].sort((a, b) => a - b);

// 1. Matemáticas Básicas
const cantidad = numbers.length;
const suma = numbers.reduce((a, b) => a + b, 0);
const promedio = suma / cantidad;
const minimo = sorted[0];
const maximo = sorted[cantidad - 1];

// 2. Matemáticas Avanzadas (Mediana, Varianza, Desviación Estándar)
const mid = Math.floor(cantidad / 2);
const mediana = cantidad % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
const varianza = numbers.reduce((a, b) => a + Math.pow(b - promedio, 2), 0) / cantidad;
const desviacion = Math.sqrt(varianza);

// 3. Frecuencias y Moda
const frecuencias = {};
numbers.forEach(n => frecuencias[n] = (frecuencias[n] || 0) + 1);
const maxFreq = Math.max(...Object.values(frecuencias));
const moda = Object.keys(frecuencias).filter(k => frecuencias[k] === maxFreq).map(Number);

// 4. Categorización de Enteros (Pares, Impares, Primos)
const enteros = numbers.filter(n => Number.isInteger(n));
const pares = enteros.filter(n => n % 2 === 0).sort((a,b)=>a-b);
const impares = enteros.filter(n => n % 2 !== 0).sort((a,b)=>a-b);

const isPrime = num => {
    if (num <= 1) return false;
    for (let i = 2; i <= Math.sqrt(num); i++) if (num % i === 0) return false;
    return true;
};
const primos = enteros.filter(isPrime).sort((a,b)=>a-b);

return {
  json: {
    cantidad,
    suma: Number(suma.toFixed(2)),
    promedio: Number(promedio.toFixed(2)),
    mediana: Number(mediana.toFixed(2)),
    desviacion: Number(desviacion.toFixed(2)),
    moda: maxFreq === 1 ? [] : moda,
    minimo,
    maximo,
    lista_desc: [...sorted].reverse(),
    lista_asc: sorted,
    positivos: numbers.filter(n => n >= 0).sort((a,b)=>b-a),
    negativos: numbers.filter(n => n < 0).sort((a,b)=>a-b),
    pares,
    impares,
    primos,
    frecuencias
  }
};
